<?php
require __DIR__.'/../bootstrap.php';require_admin();
$metricLabels=['registered_users_display'=>'Registered Users','active_users_display'=>'Active Users','tasks_created_counter'=>'Tasks Created','notes_created_counter'=>'Notes Created','projects_created_counter'=>'Projects Created'];
$intervals=[60=>'1 minute',600=>'10 minutes',3600=>'1 hour',21600=>'6 hours',43200=>'12 hours',86400=>'1 day',604800=>'1 week',2592000=>'1 month'];
$rules=platform_autofill_rules();$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)post('action','');
 if($action==='save'){
   foreach($metricLabels as $key=>$label){$v=max(0,(int)post($key,'0'));$maxValue=max(0,(int)post('max_'.$key,'0'));if($maxValue>0)$v=min($v,$maxValue);set_setting($key,(string)$v);$rules[$key]=['enabled'=>post('enabled_'.$key)?true:false,'mode'=>in_array(post('mode_'.$key),['manual','auto'],true)?post('mode_'.$key):'manual','unit'=>in_array(post('unit_'.$key),['number','percent'],true)?post('unit_'.$key):'number','amount'=>max(0,(float)post('amount_'.$key,'1')),'max'=>$maxValue,'interval'=>array_key_exists((int)post('interval_'.$key),$intervals)?(int)post('interval_'.$key):600,'last_run'=>time()];}
   set_setting('show_live_workspace_homepage',post('show_live_workspace_homepage')?'1':'0');
   set_setting('latest_month_linked',post('latest_month_linked')?'1':'0');
   if(post('latest_month_linked'))set_setting('latest_month_users',setting('registered_users_display','0')??'0');
   platform_autofill_save($rules);$msg='Platform activity and Auto-Fill settings saved. Changes are live immediately.';
 }
 if($action==='reset'){$rules=platform_autofill_defaults();platform_autofill_save($rules);foreach($metricLabels as $key=>$label)set_setting($key,$key==='registered_users_display'?'2':($key==='active_users_display'?'1':($key==='tasks_created_counter'?'1070063':($key==='notes_created_counter'?'1560021':'503098'))));set_setting('latest_month_linked','1');set_setting('show_live_workspace_homepage','1');set_setting('latest_month_users',setting('registered_users_display','2')??'2');$msg='Auto-Fill restored to disabled defaults.';}
}
platform_autofill_apply();$stats=platform_stats();
$title='Platform Activity';require __DIR__.'/../includes/header.php';
?>
<div class="page-head"><div><span class="eyebrow">Administration</span><h1>Platform Activity & Auto-Fill</h1><p>Control demo/live counters, latest-month linking, and scheduled number or percentage growth.</p></div><a class="btn secondary" href="/admin/site-editor/?focus=activity-counters">Site Editor</a></div>
<?php if($msg):?><div class="flash success"><?=e($msg)?></div><?php endif;?>
<section class="card form-card" id="latest-month"><h2>Latest Month</h2><p class="muted">When linked, Latest Month users always equals the public Registered Users value. This keeps the two figures consistent.</p><label class="check"><input type="checkbox" name="latest_month_linked" form="activity-form" value="1" <?=setting('latest_month_linked','1')==='1'?'checked':''?>> Link Latest Month users to Registered Users</label><div class="grid2"><div class="metric-preview"><span>Registered Users</span><strong data-platform-stat="registered_users"><?=number_format($stats['registered_users'])?></strong></div><div class="metric-preview"><span>Latest Month</span><strong data-platform-stat="latest_month_users"><?=number_format($stats['latest_month_users'])?></strong></div></div></section>
<form method="post" id="activity-form" class="card form-card" style="margin-top:18px"><?=csrf_field()?><input type="hidden" name="action" value="save"><h2>Counter controls</h2><label class="check" style="display:flex;align-items:center;gap:10px;padding:14px 0"><input type="checkbox" name="show_live_workspace_homepage" value="1" <?=setting('show_live_workspace_homepage','1')==='1'?'checked':''?>> <strong>Show Live Workspace Section on Homepage</strong></label><p class="muted">When turned off and saved, the complete LIVE WORKSPACE section is hidden from the public homepage. Counter settings continue to be available to the dashboard and APIs.</p><p class="muted">Disable Auto-Fill for a metric to keep it unchanged. Manual mode adds exactly the configured amount; Auto mode chooses a random increment up to the configured amount.</p>
<?php foreach($metricLabels as $key=>$label):$r=$rules[$key];?>
<div class="autofill-row setting-target" id="autofill-<?=e($key)?>"><div class="autofill-title"><h3><?=e($label)?></h3><strong data-platform-stat="<?=e(['registered_users_display'=>'registered_users','active_users_display'=>'active_users','tasks_created_counter'=>'tasks','notes_created_counter'=>'notes','projects_created_counter'=>'projects'][$key])?>"><?=number_format((int)($stats[str_replace(['registered_users_display','active_users_display','tasks_created_counter','notes_created_counter','projects_created_counter'],['registered_users','active_users','tasks','notes','projects'],$key)]??0))?></strong></div><div class="grid2"><label>Current value<input type="number" min="0" name="<?=e($key)?>" value="<?=e(setting($key,'0'))?>"></label><label>Maximum limit<input type="number" min="0" name="max_<?=e($key)?>" value="<?=e((string)$r['max'])?>"><small class="muted">0 = no maximum</small></label><label>Auto-Fill <select name="enabled_<?=e($key)?>"><option value="0">Disabled</option><option value="1" <?=$r['enabled']?'selected':''?>>Enabled</option></select></label><label>Growth mode<select name="mode_<?=e($key)?>"><option value="manual" <?=$r['mode']==='manual'?'selected':''?>>Manual</option><option value="auto" <?=$r['mode']==='auto'?'selected':''?>>Auto (random up to amount)</option></select></label><label>Growth unit<select name="unit_<?=e($key)?>"><option value="number" <?=$r['unit']==='number'?'selected':''?>>Number</option><option value="percent" <?=$r['unit']==='percent'?'selected':''?>>Percentage (%)</option></select></label><label>Amount / maximum random growth<input type="number" min="0" step="0.01" name="amount_<?=e($key)?>" value="<?=e((string)$r['amount'])?>"></label><label>Interval<select name="interval_<?=e($key)?>"><?php foreach($intervals as $sec=>$txt):?><option value="<?=$sec?>" <?=$r['interval']===$sec?'selected':''?>><?=e($txt)?></option><?php endforeach;?></select></label></div></div>
<?php endforeach;?><div class="notice"><strong>How it works:</strong> Example: Number + Manual + 10 + 10 minutes adds 10 every interval. Number + Auto + 100 chooses a random number between 1 and 100. Percentage + Manual + 20% adds 20% each interval. Percentage + Auto + 50% chooses a random percentage from 1% to 50%. Values are capped by Maximum Limit when one is set.</div><button class="btn">Save Activity & Auto-Fill</button></form>
<form method="post" style="margin-top:12px" onsubmit="return confirm('Reset Auto-Fill settings?')"><?=csrf_field()?><input type="hidden" name="action" value="reset"><button class="btn danger small">Reset Auto-Fill Defaults</button></form>
<script src="/assets/js/platform-stats.js?v=19.72" defer></script>
